BEGIN;

-- Ficha de Las Chicas del Can: documentos editoriales en y es, referencias,
-- espejo legacy, año de formación y el platino venezolano de 1988.
--
-- Decisiones editoriales:
--  * birth_year = 1976, el año en que Belkis Concepción reúne Las Muchachas.
--    La fundadora cuenta el cincuentenario desde ahí. El nombre "Las Chicas
--    del Can" llega hacia 1981 y el trabajo formal en 1982.
--  * ended sigue en false: la agrupación no se disolvió. Desde 2024-2026 hay
--    más de una nómina activa y la titularidad del nombre está en disputa
--    entre Belkis Concepción, la Corporación Wilfrido Vargas y la licencia
--    que opera en Venezuela. Una sola ficha documenta el conflicto entero.

-- 1. Año de formación
UPDATE artists SET birth_year = 1976 WHERE slug = 'las-chicas-del-can';

-- 2. Certificación de ventas documentada
INSERT INTO artist_awards (artist_id, award_id, category_id, year, work, won, source)
SELECT a.id, cat.award_id, cat.id, 1988, 'Juana la Cubana; platino en Venezuela por 100.000 copias del disco y otro por 50.000 del sencillo', true, 'Wikipedia (es)'
  FROM artists a, award_categories cat JOIN awards aw ON aw.id = cat.award_id
 WHERE a.slug = 'las-chicas-del-can' AND aw.name = 'Sales Certifications' AND cat.name = 'Platinum Records'
   AND NOT EXISTS (SELECT 1 FROM artist_awards w WHERE w.artist_id=a.id AND w.category_id=cat.id AND w.year=1988);

